use actix_web::{http::StatusCode,HttpResponse,ResponseError};use thiserror::Error;#[derive(Debug,Error)]pub enum ApiError{#[error("Not found")]NotFound,#[error("Bad request: {0}")]BadRequest(String),#[error(transparent)]Sqlx(#[from] sqlx::Error),#[error(transparent)]Anyhow(#[from] anyhow::Error),}impl ResponseError for ApiError{fn status_code(&self)->StatusCode{match self{ApiError::NotFound=>StatusCode::NOT_FOUND,ApiError::BadRequest(_)=>StatusCode::BAD_REQUEST,_=>StatusCode::INTERNAL_SERVER_ERROR}}fn error_response(&self)->HttpResponse{HttpResponse::build(self.status_code()).json(serde_json::json!({"error": self.to_string()}))}}pub type Result<T>=std::result::Result<T,ApiError>;